function pngText(buffer, key) {
  const signature = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])
  if (!buffer.subarray(0, 8).equals(signature)) return null
  let cursor = 8
  while (cursor + 12 <= buffer.length) {
    const length = buffer.readUInt32BE(cursor)
    if (cursor + length + 12 > buffer.length) return null
    const type = buffer.toString('ascii', cursor + 4, cursor + 8)
    if (type === 'tEXt') {
      const value = buffer.subarray(cursor + 8, cursor + 8 + length)
      const split = value.indexOf(0)
      if (split >= 0 && value.toString('latin1', 0, split) === key) return value.toString('latin1', split + 1)
    }
    cursor += length + 12
  }
  return null
}
if (refreshPng) {
  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'personalfitness-partner-sheet-'))
  try {
    const prefix = path.join(tempDir, 'first-page')
    execFileSync('pdftoppm', ['-f', '1', '-singlefile', '-scale-to-x', '1400', '-scale-to-y', '-1', '-png', pdfPath, prefix], { stdio: 'inherit' })
    execFileSync('python3', ['-c', 'from PIL import Image, PngImagePlugin; import sys; im=Image.open(sys.argv[1]); meta=PngImagePlugin.PngInfo(); meta.add_text(sys.argv[3],sys.argv[4]); im.save(sys.argv[2],pnginfo=meta,optimize=True)', `${prefix}.png`, pngPath, stampKey, sourceHash], { stdio: 'inherit' })
  } finally { await fs.rm(tempDir, { recursive: true, force: true }) }
}
let png
try { png = await fs.readFile(pngPath) } catch { png = null }
if (!png || pngText(png, stampKey) !== sourceHash) {
  throw new Error('The WhatsApp PNG is missing or stale. Run node scripts/generate-partner-assets.mjs --refresh-png locally with Poppler and Pillow, then commit the PDF, PNG, photograph and generator together. Production builds need neither Poppler nor Pillow.')
}
